if Yb==RLe[2281]or Yb==RLe[1185]or Yb==RLe[2282]then
return Wb
end
if Yb~=RLe[2280]or(Xb or 0)>6 then
return nil
end
local Zb={}
for _b,cc in pairs(Wb)do
