end
end
return Zb
end
function F.log(dc,ec,fc)
if dc>(O.logLevel or 1)then
return
end
local gc=string.format(RLe[2283],os.date(RLe[2284]),ec,tostring(fc))
table.insert(R.lines,gc)
if#R.lines>250 then
table.remove(R.lines,1)
end
table.insert(R.pending,gc)
local hc=tostring(fc):lower()
if hc:find(RLe[2285])or hc:find(RLe[2286])or hc:find(RLe[2287])or ec==RLe[2288]then
R.problems=R.problems or{}
