bm[fm.Value]=(bm[fm.Value]or 0)+1
end
end
for hm,im in ipairs(bb.team or{})do
if im.id~=am.id and not V.isFarm(im.id)and im.u and im.uuid and(bm[im.uuid]or 0)<V.cap(im.u)then
