local Mm,Nm=F.request(RLe[2479],RLe[2371],vm)
if Mm and Nm then
table.insert(bb.actions,RLe[2676]..Lm..RLe[2677])
F.log(1,RLe[2669],string.format(RLe[2678],V.name(am.id),Lm,ym or 0,U.fmt(wm or 0),V.name(am.id)))
return true
end
F.log(1,RLe[2669],string.format(RLe[2679],V.name(am.id),Lm,tostring(Nm)))
return false
end
function pb.nearCast(Om,Pm,Qm)
