if(Bp.sold or 0)>0 then
if Bp.id~=dp then
yp=yp+1
end
if Cp>0 then
if Bp.id==dp then
rp=rp+1
else
wp=wp+1
end
zp=math.max(zp,Cp)
end
elseif Cp>0 then
vp=vp+1
end
end
if rp>0 and vp==0 and(not pp or rp>pp)then
op,pp={name=qp,other=wp,otherAfter=yp,top=zp},rp
end
end
