end
if fp.chance and(cp.nearN or 0)>0 then
Xp.chanceSeen=math.floor(math.min(1,Wp.foes/cp.nearN)*100+0.5)/100
end
Xp.bossToo=Wp.boss>0 or nil
return{seen=true,buff=Qp,nums=Xp,why=string.format(RLe[2703],Wp.foes,Qp)}
end
if ep.family==RLe[2534]then
