end
if ep.family==RLe[2378]then
local eq={}
for fq,gq in ipairs(cp.summons)do
if gq.owner==dp then
table.insert(eq,gq)
end
end
if#eq<2 then
return{why=RLe[2707]}
end
table.sort(eq,function(hq,iq)
return hq.born<iq.born
end)
local jq,kq,lq={},{},{}
