tq=math.max(tq,sq)
end
local wq=mp(kq)
return{seen=true,nums={everySeen=mp(jq),lifeSeen=wq and math.floor(wq+0.5)or nil,capSeen=tq,made= #eq},why=string.format(RLe[2708],#eq)}
end
if ep.family==RLe[2481]then
local xq,yq
for zq,Aq in pairs(cp.own)do
if(Aq.by[dp]or 0)>0 and Aq.first>=ip-1 and(not xq or(jp[zq]and not jp[xq]))then
xq,yq=zq,Aq
end
