if not Eq then
return{why=RLe[2709]}
end
return{seen=true,nums={stat=Eq,loSeen=Fq,hiSeen=Gq,transformTo=Bq},why=string.format(RLe[2710],Eq,tostring(Fq),tostring(Gq))}
end
return{seen=true,buff=xq,nums={maxSeen=yq.max,steps= #yq.vals,transformTo=Bq},why=string.format(RLe[2711],xq,tostring(yq.max))}
end
if ep.family==RLe[2478]then
local Lq,Mq,Nq={},{},nil
for Oq,Pq in ipairs(cp.steps)do
for Qq,Rq in pairs(Pq.reset or{})do
table.insert(Lq,Rq)
table.insert(Mq,Pq.drop)
Nq=Nq or Qq
