function mb.charmApplies(dD)
if not dD then
return false
end
if dD.kind==RLe[2303]and mb.is(dD.level)then
return true
end
return dD.kind==RLe[2751]and tostring(dD.level):find(RLe[2815],1,true)~=nil
end
function mb.charms()
local eD=N.prof()
local fD={}
for gD,hD in pairs((eD and eD.inventory and eD.inventory.unique_items)or{})do
local iD=type(hD)==RLe[2280]and N.Items[hD.item_id]
if type(iD)==RLe[2280]and iD.item_group==RLe[2816]then
local jD={uuid=hD.uuid or gD,id=hD.item_id,tier=tonumber(iD.tier)or 0,rolls={}}
local kD=type(hD._unique_item_data)==RLe[2280]and hD._unique_item_data._unique_charm_data
jD.worn=type(kD)==RLe[2280]and kD._e~=nil
local lD=type(kD)==RLe[2280]and kD._d
for mD,nD in pairs(type(lD)==RLe[2280]and lD or{})do
if type(nD)==RLe[2280]and nD._t then
jD.rolls[tostring(nD._t)]=(jD.rolls[tostring(nD._t)]or 0)+(tonumber(nD._d)or 0)
end
end
table.insert(fD,jD)
end
end
return fD
end
function mb.charmOn()
