for OD,PD in ipairs(mb.charms())do
local QD=mb.charmScore(PD,LD)
if not ND or QD>ND then
MD,ND=PD,QD
end
end
if not MD then
return nil
end
local RD=mb.charmOn()or(F.where==RLe[2361]and P.charm.uuid)or nil
if RD==MD.uuid then
return nil
end
return MD,RD
end
function mb.charmTick(SD)
local TD,UD=mb.charmWant(SD)
if not TD then
return
end
UD=mb.charmOn()
if UD then
F.request(RLe[2825],RLe[2826],UD)
task.wait(1)
end
