local VD=U.now()
while U.now()-VD<4 and mb.charmOn()~=TD.uuid do
task.wait(0.5)
end
if mb.charmOn()==TD.uuid then
P.charm.uuid,P.charm.at,P.charm.failAt=TD.uuid,os.time(),nil
F.saveSoon()
F.log(1,RLe[2828],string.format(RLe[2829],mb.charmWords(TD),tostring(SD.label),math.floor((tonumber(SD.p)or 0)*100+0.5),(tonumber(SD.p)or 0)>=0.92 and RLe[2820]or RLe[2730]))
else
P.charm.failAt=os.time()
F.saveSoon()
F.log(1,RLe[2828],string.format(RLe[2830],mb.charmWords(TD)))
end
end
function mb.charmSlots()
return tonumber(N.GS and N.GS.MAX_CHARM_SLOTS)or 8
end
function mb.charmSellPlan(WD)
WD=WD or mb.charms()
local XD=mb.charmSlots()
local YD=math.max(1,math.min(XD-2,math.floor(tonumber(O.charmFree)or 2)))
local ZD= #WD-(XD-YD)
if ZD<=0 then
return{},#WD,XD,YD
end
local _D=mb.charmOn()
local aE={}
for bE,cE in ipairs(WD)do
cE.total=0
for dE,eE in pairs(cE.rolls)do
cE.total=cE.total+eE
if not aE[dE]or eE>(aE[dE].rolls[dE]or 0)then
aE[dE]=cE
end
end
end
local fE={}
for gE,hE in pairs(aE)do
fE[hE]=true
end
local iE={}
for jE,kE in ipairs(WD)do
if not fE[kE]and not kE.worn and kE.uuid~=_D and kE.tier<4 then
table.insert(iE,kE)
end
end
table.sort(iE,function(lE,mE)
if math.abs(lE.total-mE.total)>1e-9 then
return lE.total<mE.total
end
return lE.tier<mE.tier
end)
local nE={}
for oE=1,math.min(ZD,#iE)do
table.insert(nE,iE[oE])
end
return nE,#WD,XD,YD
end
function mb.charmSellTick()
