local AE=F.gameSaid(wE)
F.log(1,RLe[2828],string.format(RLe[2833],#sE,tostring(AE or yE or RLe[2834])))
F.backoff(RLe[2831],1800)
return
end
cb.add(string.format(RLe[2835],#sE),#sE,RLe[2836],string.format(RLe[2837],rE-zE,rE,table.concat(tE,RLe[2838])))
end
function mb.weatherStrength(BE)
local CE=mb.fx(BE)
local DE=CE.dmg/CE.cd/CE.hp/CE.speed*(1+(CE.range-1)/2)
for EE,FE in pairs(CE.kinds)do
DE=DE*(1+bb.rogueShare(EE)*FE)
end
if CE.ice>0 then
local GE=bb.rogueShare(RLe[2431])
DE=DE*(GE+(1-GE)/(1-CE.ice+CE.ice/gb.modFactor(RLe[2839])))
end
if CE.fly>0 then
DE=DE*(1-CE.fly*0.5)
end
if CE.noCC then
DE=DE*0.95
end
if CE.shroud then
DE=DE*0.9
end
if CE.zap then
DE=DE*0.85
end
return DE/mb.weatherK(BE)
end
mb.WEATHER_K_MIN,mb.WEATHER_K_MAX,mb.WEATHER_K_RUNS=0.5,4,10
function mb.weatherK(HE)
local IE=HE and type(P.hunt)==RLe[2280]and type(P.hunt.wk)==RLe[2280]and P.hunt.wk[tostring(HE)]or nil
return type(IE)==RLe[2280]and tonumber(IE.k)or 1
end
function mb.weatherLearn()
if bb.withOthers or#game:GetService(RLe[1178]):GetPlayers()>1 then
return
end
local JE=bb.huntWeather or mb.weatherNow()
local KE,LE=bb.pred,bb.calRun
if not JE or type(KE)~=RLe[2280]or type(LE)~=RLe[2280]then
return
end
local function ME(NE,OE)
return type(NE)==RLe[2280]and tonumber(NE[OE]or NE[tostring(OE)])or nil
end
local PE={}
for QE=2,bb.wave()do
local RE,SE=ME(LE.alive,QE),ME(KE.aliveAt,QE)
if RE and SE and RE>0 and SE>0 then
table.insert(PE,RE/SE)
end
end
if#PE<3 then
return
end
table.sort(PE)
local TE=PE[math.ceil(#PE/2)]
P.hunt.wk=type(P.hunt.wk)==RLe[2280]and P.hunt.wk or{}
local UE=P.hunt.wk[tostring(JE)]
local VE=math.min(mb.WEATHER_K_RUNS-1,type(UE)==RLe[2280]and tonumber(UE.n)or 0)
local WE=mb.weatherK(JE)
local XE=math.max(1,VE)
local YE=math.exp((XE*math.log(WE)+math.log(WE*TE))/(XE+1))
YE=U.clamp(YE,mb.WEATHER_K_MIN,mb.WEATHER_K_MAX)
bb.wkWas={w=tostring(JE),old=UE}
P.hunt.wk[tostring(JE)]={k=YE,n=(type(UE)==RLe[2280]and tonumber(UE.n)or 0)+1,at=os.time()}
F.log(1,RLe[2840],string.format(RLe[2841],tostring(JE),TE,tostring(JE),YE,WE,P.hunt.wk[tostring(JE)].n))
end
function mb.cardGems(ZE,_E)
local aF=0
local bF=mb.pearlsFrom(_E+1,50)
for cF,dF in pairs(type(ZE.effects)==RLe[2280]and ZE.effects or{})do
if type(dF)==RLe[2280]then
local eF=tonumber(dF.amount)or 0
if dF.type==RLe[2842]then
aF=aF+math.abs(eF)*bF*O.pearlValue
elseif dF.type==RLe[2843]then
local fF,gF=pcall(W.rewardValue,dF.reward)
if fF then
aF=aF+(tonumber(gF)or 0)
end
elseif dF.type==RLe[2844]then
aF=aF+eF*mb.STARFALL_GEMS
elseif dF.type==RLe[2845]then
aF=aF+eF*100
end
end
end
if ZE.option_type==RLe[2846]then
aF=aF+mb.HARD_GEMS
end
if ZE.weather then
local hF=ZE.weather~=mb.weatherNow()
if hF and ZE.weather==RLe[2781]then
aF=aF+mb.starfallRemnants(50-(tonumber(_E)or 0))*W.remnantGems(RLe[2785])
end
local iF=mb.board()
if hF and iF and ZE.weather~=RLe[2787]and not iF.weathers[ZE.weather]then
aF=aF+(1000+5000*O.pearlValue+50*W.remnantGems(RLe[2785]))/mb.WEATHERS
end
end
return aF
end
