if _F>0 and N.Units[ZF.unit_id]and V.rows(ZF.unit_id)and not V.hidden(ZF.unit_id)then
local aG,bG=pcall(N.USC.calculate_level,ZF.unit_id,tonumber(ZF.xp)or 0)
if V.isFarm(ZF.unit_id)or not VF or(aG and(tonumber(bG)or 0)>=gb.GROWN_LEVEL)then
local cG,dG=pcall(V.score,ZF,FF.mod)
dG=(cG and tonumber(dG)or 0)*V.eventMul(ZF,FF.ld)
