WF[ZF.unit_id]={u=ZF,d=_F,sc=dG}
end
end
end
end
local eG={}
for fG,gG in pairs(WF)do
table.insert(eG,gG)
end
table.sort(eG,function(hG,iG)
if hG.d~=iG.d then
return hG.d>iG.d
end
return hG.sc>iG.sc
end)
if#eG==0 then
return nil
end
local jG,kG=table.clone(GF),{}
local lG=mb.teamDrop(jG,MF)
local mG=gb.realShares(FF.key,5)
local function nG(oG)
local pG,qG={},0
pcall(gb.run,FF,gb.teamFrom(oG,FF.map),{hpMul=1,dealt=pG})
task.wait()
for rG,sG in pairs(pG)do
qG=qG+(tonumber(sG)or 0)
end
local tG={}
for uG,vG in ipairs(oG)do
tG[vG.unit_id]=tonumber(mG[vG.unit_id])or(((tonumber(pG[V.name(vG.unit_id)])or 0)+(tonumber(pG[RLe[2866]..tostring(vG.unit_id)])or 0))/math.max(1,qG))
end
return tG
end
local wG=nG(jG)
for xG=1,mb.BONUS_SWAPS do
if mb.teamDrop(jG,MF)>=1 or U.now()-IF>HF then
break
end
local yG=false
for zG,AG in ipairs(eG)do
if U.now()-IF>HF then
break
end
local BG=false
for CG,EG in ipairs(jG)do
if EG.uuid==AG.u.uuid or V.sameGroup(EG.unit_id,AG.u.unit_id)then
BG=true
break
end
end
if not BG then
local FG={}
for GG,HG in ipairs(jG)do
if(mb.unitDrop(HG,MF))<AG.d then
table.insert(FG,{i=GG,sc=(tonumber(wG[HG.unit_id])or 0)+((V.isFarm(HG.unit_id)or V.allyBuff(HG.unit_id))and 1e300 or 0)})
end
end
