if Vcb.equipped then
Rcb=Rcb+1
Scb[Vcb.item_id]=true
elseif ab.DEF_WANT[Vcb.item_id]and(Vcb.d==nil or Vcb.d>0)then
table.insert(Tcb,Vcb)
end
end
local Wcb={}
while Rcb+ #Wcb<Qcb and#Tcb>0 do
table.sort(Tcb,function(Xcb,Ycb)
local Zcb,_cb=Scb[Xcb.item_id]and 1 or 0,Scb[Ycb.item_id]and 1 or 0
if Zcb~=_cb then
return Zcb<_cb
end
if ab.DEF_WANT[Xcb.item_id]~=ab.DEF_WANT[Ycb.item_id]then
return ab.DEF_WANT[Xcb.item_id]<ab.DEF_WANT[Ycb.item_id]
end
return Xcb.g>Ycb.g
end)
local adb=table.remove(Tcb,1)
Scb[adb.item_id]=true
table.insert(Wcb,adb)
end
