function kb.relicWorth(Wfb,Xfb)
local Yfb=Xfb._unique_item_data and Xfb._unique_item_data._unique_relic_data
if not Yfb then
return 0
end
local Zfb=N.Items[Xfb.item_id]or{}
local _fb,agb=V.types(Wfb.unit_id)
if Zfb.main_damage_type and Zfb.main_damage_type~=RLe[2983]and Zfb.main_damage_type~=agb then
return 0
end
local bgb,cgb=0,0
for dgb,egb in pairs(Yfb._core_damage_type_buffs or{})do
if _fb[egb.damage_type]then
bgb=bgb+(tonumber(egb.mul)or 0)+(tonumber(egb.add_upg)or 0)*0.01+(tonumber(egb.pen)or 0)*0.001
cgb=cgb+(tonumber(egb.crit)or 0)
end
end
bgb=bgb+cgb*0.5
local fgb=V.rows(Wfb.unit_id)
local ggb=fgb and fgb[fgb.max]
local hgb=(ggb and tonumber(ggb.cd)or 0)*V.mult(Wfb,RLe[2731])
for igb,jgb in pairs(Yfb._unique_relic_effects or{})do
local kgb=type(jgb.params)==RLe[2280]and jgb.params or{}
if jgb.id==RLe[3389]then
local lgb=math.min(1,(tonumber(kgb.extra_damage)or 0)*hgb/math.max(1,tonumber(kgb.time_interval)or 40))
local mgb=V.DRONES and V.DRONES[Wfb.unit_id]
if mgb and mgb.late and hgb>0 then
local ngb=1/hgb
lgb=lgb*ngb/(ngb+(tonumber(mgb.max)or 0)*(tonumber(mgb.late.dmg)or 0)*(tonumber(mgb.hits)or 1)/math.max(0.1,tonumber(mgb.late.cd)or 4))
end
bgb=bgb+lgb
elseif jgb.id==RLe[3390]then
bgb=bgb+(tonumber(kgb.dmg_buff)or 0)*0.25
elseif jgb.id==RLe[3391]then
bgb=bgb+(tonumber(kgb.dmg_buff)or 0)*cgb
elseif jgb.id==RLe[3392]then
if _fb.magic then
bgb=0
else
bgb=bgb+(tonumber(kgb.dmg_buff)or 0)*0.3
end
elseif jgb.id==RLe[3393]then
if _fb.water_damage then
bgb=bgb+0.05
end
elseif jgb.id==RLe[2432]then
local ogb=tonumber(kgb.duration_buff)or tonumber(type(jgb.static_params)==RLe[2280]and jgb.static_params.duration_buff)or 2
local pgb,qgb=pcall(V.attackInfo,ggb and ggb.atk,ggb and ggb.range)
local rgb,sgb=pgb and tonumber(qgb.burn)or 0,pgb and tonumber(qgb.dot)or 0
if rgb<=0 then
local tgb,ugb=pcall(pb.model,Wfb.unit_id,pgb and qgb or nil,ggb)
if tgb and type(ugb)==RLe[2280]and(tonumber(ugb.burnDot)or 0)>0 then
rgb,sgb=ugb.burnDot,sgb+(tonumber(ugb.dot)or 0)
end
end
bgb=bgb+rgb*math.max(0,ogb-1)/(1+sgb)
end
end
return bgb
end
function kb.relicPlan()
