local Dgb=Cgb.data and Cgb.data.rarity
if not V.isFarm(Cgb.id)and(Dgb==RLe[2870]or Dgb==RLe[2871]or Dgb==RLe[3387]or Dgb==RLe[3394])then
local Egb=kb.share(Cgb.id)
if not P.str.share[Cgb.id]then
Egb=math.min(Egb,0.15)
end
local Fgb={}
