if Cgb.u._equipped_relic then
local Qgb=false
for Rgb,Sgb in ipairs(Lgb)do
if Sgb.it.uuid==Cgb.u._equipped_relic then
Qgb=true
end
end
local Tgb=not Qgb and vgb.inventory:get_item_by_uuid(Cgb.u._equipped_relic)
if Tgb then
table.insert(Lgb,{it=Tgb,w=kb.relicWorth(Cgb.u,Tgb)*Egb*100})
end
end
table.insert(Agb,{e=Cgb,share=Egb,opts=Lgb})
end
end
local Ugb,Vgb={},-1
local Wgb,Xgb,Ygb={},{},{}
local function Zgb(_gb,ahb)
if _gb> #Agb then
if ahb>Vgb then
Vgb=ahb
