if not Xgb[dhb.it.uuid]and not(ehb and Ygb[dhb.it.item_id])then
Xgb[dhb.it.uuid]=true
if ehb then
Ygb[dhb.it.item_id]=true
end
Wgb[bhb.e.uuid]=dhb.it.uuid
Zgb(_gb+1,ahb+dhb.w+(dhb.it.uuid==bhb.e.u._equipped_relic and 0.01 or 0))
Wgb[bhb.e.uuid]=nil
Xgb[dhb.it.uuid]=nil
if ehb then
Ygb[dhb.it.item_id]=nil
end
end
end
end
Zgb(1,0)
local fhb,ghb=0,{}
