local Wib=math.min(9,tonumber(Vib.story_world_rank)or tonumber(Uib.rank)or 9)
local Xib=tonumber(Vib.story_level_rank)or 6
local Yib=(Uib.kind==RLe[2329]and 1.5 or 1)*(Wib>5 and 2 or 1)
local Zib=2.1564^(Wib-1)*(40+10*Xib)/Yib
if Uib.kind==RLe[2305]then
Zib=3*30*2.1564^(Wib-1)/Yib
end
local _ib=Wib>=9 and 0.3 or(Wib>=7 and 0.5 or 1)
