local xjb=wjb.xp*qjb
local yjb=math.min(wjb.n,math.floor((rjb-tjb)/math.max(1,xjb)))
if yjb>0 then
sjb[wjb.id]=yjb
tjb=tjb+yjb*xjb
ujb=ujb+yjb
end
end
return{feed=sjb,planned=tjb,n=ujb}
end
function kb.run(zjb)
