Nmb=Mmb and tonumber(Nmb)or 0
if Nmb>0 then
table.insert(Fmb,{uuid=Hmb,id=Imb.unit_id,xp=Nmb,rarity=Jmb.rarity})
Gmb=Gmb+Nmb
end
end
end
