function ib.boost(Lob,Mob,Nob,Oob)
if Mob<2 or Nob>=math.min(O.dangerReach,(Oob or 1)*0.9)then
return
end
local Pob=Nob<math.min(O.safeReach,(Oob or 1)*0.75)
local Qob=0
for Rob,Sob in ipairs(Lob)do
if not Sob.farm and not Sob.train and Sob.cost>0 then
Qob=math.max(Qob,Sob.gain/Sob.cost)
end
end
for Tob,Uob in ipairs(Lob)do
if Uob.train==RLe[3571]or(Uob.train==RLe[3572]and Pob)then
Uob.gain=math.max(Uob.gain,Qob*Uob.cost*1.05)
end
end
end
