Tqb={out=Eqb[Mqb[Uqb].i].unit_id,r=Yqb,rate=Zqb,trial=Vqb}
end
end
end
Aqb.ownMin=Jqb.t/60
if not Tqb then
Aqb.why=Kqb and string.format(RLe[3587],Lqb,wqb and RLe[3588]or RLe[3589])or wqb and RLe[3590]or RLe[3591]
else
Aqb.out,Aqb.tk,Aqb.minutes=Tqb.out,Tqb.r.tk or 0,Tqb.r.t/60
Aqb.uuids={}
