function eb.upgradeGain(SLb,TLb,ULb,VLb,WLb,XLb)
local YLb,ZLb=TLb[ULb],TLb[ULb+1]
local _Lb=(YLb.cd>0 and YLb.damage/YLb.cd or 0)
local aMb=(ZLb.cd>0 and ZLb.damage/ZLb.cd or 0)*V.aoe(ZLb.atk,ZLb.range)/math.max(0.3,V.aoe(YLb.atk,YLb.range))
local bMb=_Lb>0 and SLb*(aMb/_Lb-1)or(XLb or 0)
local cMb=TLb[ULb+2]
if cMb and ULb+1<TLb.max and cMb.cd>0 and ZLb.cd>0 and _Lb>0 then
local dMb=SLb*((cMb.damage/cMb.cd)/_Lb-1)
local eMb=VLb+cMb.cost*WLb
if dMb/eMb>bMb/VLb then
bMb=bMb+(dMb/eMb*VLb-bMb)*0.5
end
end
local fMb=(ZLb.range or 0)>(YLb.range or 0)and(1+((ZLb.range-YLb.range)/math.max(1,YLb.range)))or 1
return math.max(0,bMb)*fMb
end
function eb.dpsFor(gMb,hMb)
if hMb<=0 then
return 0
end
local iMb={}
for jMb,kMb in ipairs(gMb)do
if not kMb.farm and not kMb.grif and kMb.gain>0 then
table.insert(iMb,kMb)
end
end
table.sort(iMb,function(lMb,mMb)
return lMb.gain/lMb.cost>mMb.gain/mMb.cost
end)
local nMb,oMb=0,0
for pMb,qMb in ipairs(iMb)do
if hMb<=0 then
break
end
oMb=qMb.gain/qMb.cost
local rMb=math.min(1,hMb/qMb.cost)
nMb=nMb+qMb.gain*rMb
hMb=hMb-qMb.cost*rMb
end
return nMb+math.max(0,hMb)*oMb*0.7
end
function eb.shieldDps(sMb,tMb,uMb,vMb,wMb,xMb,yMb)
if(vMb or 0)<=0 or(sMb or 0)<=0 or(wMb or 0)<=0 then
return sMb or 0
end
tMb,uMb,xMb=math.max(0.3,tMb or 2),math.max(1,uMb or 1),xMb or 1
local zMb=sMb*xMb*tMb/uMb
return wMb*uMb/((vMb/math.max(1,yMb or 1)+math.max(1,wMb/zMb))*tMb)/xMb
end
function eb.shieldGain(AMb,BMb,CMb,DMb,EMb,FMb,GMb,HMb)
local IMb,JMb=V.attackInfo(BMb.atk,BMb.range),V.attackInfo(DMb.atk,DMb.range)
local KMb=eb.shieldDps(AMb,(tonumber(BMb.cd)or 2)*(GMb or 1),IMb.n,EMb,FMb,HMb,IMb.hits)
local LMb=eb.shieldDps(CMb,(tonumber(DMb.cd)or 2)*(GMb or 1),JMb.n,EMb,FMb,HMb,JMb.hits)
local MMb=math.max(0,((tonumber(DMb.range)or 0)-(tonumber(BMb.range)or 0))/math.max(1,tonumber(BMb.range)or 1))
return math.max(0,LMb-KMb)+KMb*MMb
end
function eb.shieldWork(NMb,OMb,PMb,QMb,RMb,SMb,TMb,UMb,VMb)
if(QMb or 0)<=0 then
return 0
end
local WMb=3*QMb*(RMb or 1)/math.max(1,SMb or 20)
if(PMb or 0)>=WMb then
return 0
end
return math.max(1,NMb or 1)*math.max(1,VMb or 1)/math.max(0.3,OMb or 2)*math.min(TMb or 0,UMb or 0)
end
function eb.holdGain(XMb,YMb,ZMb,_Mb)
if not XMb or(YMb or 0)<=0 then
return 0
end
local aNb,bNb=tonumber(XMb.stun)or 0,tonumber(XMb.slowTime)or 0
if aNb<=0 and bNb<=0 then
return 0
end
local cNb,dNb=aNb>0 and aNb or bNb,aNb>0 and 1 or(tonumber(XMb.slowPct)or 0.3)
local eNb=dNb*cNb/(cNb+(tonumber(XMb.ccCd)or 8))
local fNb=eNb/math.max(0.1,1-eNb)
return YMb*fNb*U.clamp(ZMb or 0.5,0,1)*math.min(1,(tonumber(XMb.n)or 1)/2)/(1+(_Mb or 0))
end
function eb.bleedGain(gNb,hNb,iNb,jNb)
if(gNb or 0)<=0 then
return 0
end
local kNb=hNb or 0
for lNb,mNb in ipairs(iNb or{})do
kNb=math.max(kNb,(tonumber(mNb.hp)or 0)*0.5)
end
return gNb*kNb*(jNb and 0.5 or 1)
end
function eb.bleedShare(nNb,oNb,pNb,qNb)
if nNb<=0 or not oNb then
return 0
end
if qNb then
return oNb==0 and nNb or nNb/(oNb+1)
