end
if(Mmc.regen or 0)>0 then
table.insert(Omc,string.format(RLe[4237],tostring(math.floor(Mmc.regen*1000+0.5)/10)))
end
local onc=Mmc.fx
if onc then
local pnc,qnc={},{}
if math.abs((onc.hp or 1)-1)>0.001 then
table.insert(pnc,string.format(RLe[4238],onc.hp))
end
if math.abs((onc.speed or 1)-1)>0.001 then
table.insert(pnc,string.format(RLe[4239],onc.speed))
end
if(onc.fly or 0)>0 then
table.insert(pnc,string.format(RLe[4240],math.floor(onc.fly*100+0.5)))
end
if(onc.shield or 0)>0 then
table.insert(pnc,string.format(RLe[4241],math.floor(onc.shield+0.5)))
end
if(onc.burst or 0)>0 then
table.insert(pnc,(onc.burst>=1)and RLe[4242]or string.format(RLe[4243],math.floor(onc.burst*100+0.5)))
end
if(onc.ice or 0)>0 then
table.insert(pnc,string.format(RLe[4244],math.floor(onc.ice*100+0.5)))
end
if onc.starfall then
table.insert(pnc,RLe[4245])
end
if#pnc>0 then
table.insert(Omc,RLe[4246]..table.concat(pnc,RLe[2404]))
end
if math.abs((onc.dmg or 1)-1)>0.001 then
table.insert(qnc,string.format(RLe[4247],onc.dmg))
end
if math.abs((onc.cd or 1)-1)>0.001 then
table.insert(qnc,string.format(RLe[4248],onc.cd))
end
if math.abs((onc.range or 1)-1)>0.001 then
table.insert(qnc,string.format(RLe[4249],onc.range))
end
if math.abs((onc.cost or 1)-1)>0.001 then
table.insert(qnc,string.format(RLe[4250],onc.cost))
end
for rnc,snc in pairs(onc.kinds or{})do
if(tonumber(snc)or 0)~=0 then
table.insert(qnc,string.format(RLe[4251],Nmc(rnc),math.floor(snc*100+0.5)))
end
end
if(onc.crit or 0)>0 then
table.insert(qnc,string.format(RLe[4252],math.floor(onc.crit*100+0.5)))
end
if#qnc>0 then
table.insert(Omc,(Mmc.ld and type(Mmc.ld._dungeon)==RLe[2280]and RLe[4253]or RLe[4254])..table.concat(qnc,RLe[2404]))
end
end
if Mmc.ld and mb.is(Mmc.ld.id)then
local tnc=(N.data(RLe[2791])or{})[mb.weatherNow()]
if tnc and tnc.name then
