end
end
local unc=Mmc.ld and Mmc.ld._challenge and N.CAR.challenges and N.CAR.challenges[Mmc.ld._challenge]
if type(unc)==RLe[2280]and unc.name then
table.insert(Omc,RLe[4256]..tostring(unc.name))
