function gb.why(vnc,wnc)
local xnc=gb.typeWord
local ync={}
local znc=vnc and vnc.mod or{}
local Anc=vnc and vnc.fx
local Bnc={}
for Cnc,Dnc in ipairs(wnc or{})do
if V.SUMMONER[Dnc.unit_id]or V.DRONES[Dnc.unit_id]then
table.insert(Bnc,(V.name(Dnc.unit_id):gsub(RLe[3061],RLe[1199])))
end
end
local Enc=vnc and(vnc.mapFly or(vnc.flyChance or 0)>0 or(Anc and(Anc.fly or 0)>0))
for Fnc,Gnc in ipairs(wnc or{})do
local Hnc,Inc=Gnc.unit_id,{}
if V.isFarm(Hnc)then
table.insert(Inc,RLe[4257])
else
local Jnc=V.allyBuff(Hnc)
if Jnc then
local Knc,Lnc={},0
for Mnc in pairs(Jnc.types or{})do
table.insert(Knc,xnc(Mnc))
end
for Nnc,Onc in ipairs(wnc)do
if Onc~=Gnc and not V.isFarm(Onc.unit_id)then
local Pnc=V.types(Onc.unit_id)
for Qnc in pairs(Jnc.types or{})do
if Pnc[Qnc]then
Lnc=Lnc+1
break
end
end
end
end
table.sort(Knc)
table.insert(Inc,string.format(RLe[4258],#Knc>0 and table.concat(Knc,RLe[2569])or RLe[4259],Lnc))
end
if V.BLESS.by[Hnc]and#Bnc>0 then
table.insert(Inc,RLe[4260]..table.concat(Bnc,RLe[2404]))
end
if V.SUMMONER[Hnc]then
table.insert(Inc,RLe[4261])
elseif V.DRONES[Hnc]then
table.insert(Inc,RLe[4262])
end
local Rnc,Snc=pcall(V.bleeds,Hnc)
if(vnc and vnc.regen or 0)>0 and Rnc and Snc then
table.insert(Inc,string.format(RLe[4263],Snc))
end
local Tnc,Unc=pcall(bb.cardAir,Hnc)
if Enc and Tnc and Unc then
table.insert(Inc,RLe[4264])
end
local Vnc,Wnc=V.types(Hnc)
local Xnc,Ync
for Znc in pairs(Vnc)do
local _nc=znc.weak and tonumber(znc.weak[Znc])
if _nc and(not Xnc or _nc>Xnc)then
Xnc,Ync=_nc,Znc
end
end
if Xnc then
table.insert(Inc,string.format(RLe[4265],xnc(Ync),Xnc))
end
if Anc and Anc.kinds and(tonumber(Anc.kinds[Wnc])or 0)>0 then
table.insert(Inc,string.format(RLe[4266],xnc(Wnc),math.floor(Anc.kinds[Wnc]*100+0.5)))
end
if znc.res and znc.res[Wnc]then
table.insert(Inc,string.format(RLe[4267],xnc(Wnc),tonumber(znc.res[Wnc])or 1))
end
if znc.strong and znc.strong[Wnc]then
table.insert(Inc,string.format(RLe[4268],xnc(Wnc)))
end
if#Inc==0 then
table.insert(Inc,RLe[4269])
end
local aoc,boc,coc=pcall(V.mapNudge,Hnc,vnc and vnc.map,vnc and vnc.mapSig)
local doc=aoc and type(coc)==RLe[2280]and(tonumber(coc.n)or 0)or 0
if doc>0 and doc<V.MAP_RUNS then
table.insert(Inc,string.format(RLe[4270],doc))
elseif doc>=V.MAP_RUNS and math.abs((tonumber(boc)or 1)-1)>=0.03 then
table.insert(Inc,string.format(RLe[4271],boc>1 and RLe[4272]or RLe[4273],boc,doc))
elseif doc>=V.MAP_RUNS then
table.insert(Inc,string.format(RLe[4274],doc))
end
end
table.insert(ync,V.name(Hnc)..RLe[2638]..table.concat(Inc,RLe[2838]))
end
return ync
end
function gb.explainSave(eoc,foc,goc,hoc,ioc,joc,koc,loc)
if not eoc then
return
end
P.searchX=type(P.searchX)==RLe[2280]and P.searchX or{}
local moc,noc=pcall(gb.against,goc)
local ooc,poc=pcall(gb.why,goc,hoc)
local qoc,roc,soc={},{},{}
for toc,uoc in ipairs(hoc or{})do
table.insert(qoc,V.name(uoc.unit_id))
table.insert(roc,uoc.unit_id)
end
for voc,woc in ipairs(koc or{})do
table.insert(soc,woc.unit_id)
end
P.searchX[tostring(eoc)]={at=os.time(),label=tostring(foc),team=qoc,ids=roc,mine= #soc>0 and soc or nil,swapped=joc and true or nil,map=goc and goc.map or nil,against=moc and noc or{RLe[2531]},how=ioc or{},why=ooc and poc or{RLe[2531]},stats=type(loc)==RLe[2280]and loc or nil}
if U.count(P.searchX)>12 then
local xoc,yoc
for zoc,Aoc in pairs(P.searchX)do
if not yoc or(tonumber(Aoc.at)or 0)<yoc then
xoc,yoc=zoc,tonumber(Aoc.at)or 0
end
end
P.searchX[xoc]=nil
end
F.saveNow()
end
gb.SEARCH_LOG,gb.SEARCH_LOG_MAX=RLe[4275],3000000
function gb.realShares(Boc,Coc)
Coc=Coc or 5
gb._rsh=gb._rsh or{}
local Doc=gb._rsh[tostring(Boc)]
if Doc and U.now()-Doc.t<120 then
return Doc.v
end
local Eoc,Foc,Goc={},{},{}
pcall(function()
local Hoc=N.FOLDER..RLe[2569]..gb.SEARCH_LOG
if not isfile(Hoc)then
return
end
local Ioc=readfile(Hoc)
if#Ioc>600000 then
Ioc=Ioc:sub(#Ioc-600000)
end
local Joc={}
for Koc in Ioc:gmatch(RLe[3132])do
table.insert(Joc,Koc)
end
local Loc=RLe[4276]..U.json(tostring(Boc))
for Moc= #Joc,1,-1 do
if Joc[Moc]:find(Loc,1,true)then
local Noc=U.unjson(Joc[Moc])
local Ooc=type(Noc)==RLe[2280]and type(Noc.result)==RLe[2280]and Noc.result.shares
if type(Ooc)==RLe[2280]then
for Poc,Qoc in pairs(Ooc)do
if(Goc[Poc]or 0)<Coc and tonumber(Qoc)then
Foc[Poc],Goc[Poc]=(Foc[Poc]or 0)+tonumber(Qoc),(Goc[Poc]or 0)+1
end
end
end
end
end
end)
for Roc,Soc in pairs(Foc)do
Eoc[Roc]=Soc/Goc[Roc]
end
gb._rsh[tostring(Boc)]={t=U.now(),v=Eoc}
return Eoc
end
function gb.searchResult(Toc,Uoc)
local Voc=bb.kind==RLe[2306]and RLe[3042]or bb.key
local Woc=type(P.searchX)==RLe[2280]and P.searchX[tostring(Voc)]
