return
end
local Xoc,Yoc=pcall(bb.damageShares)
local Zoc={}
for _oc,apc in pairs(Xoc and type(Yoc)==RLe[2280]and Yoc or{})do
Zoc[_oc]=math.floor(apc*1000+0.5)/1000
end
local bpc={}
for cpc,dpc in ipairs(bb.team or{})do
table.insert(bpc,dpc.id)
end
Woc.result={won=Toc and true or false,wave=bb.wave(),total=bb.total,sec=math.floor(tonumber(Uoc)or 0),shares=Zoc,why=bb.lossTags,played=bpc,style=bb.style,lab=bb.labWay,eff=bb.lastEff,at=os.time()}
local epc,fpc=pcall(U.json,{at=Woc.at,key=Voc,label=Woc.label,map=Woc.map or(bb.ld and bb.ld.map),against=Woc.against,how=Woc.how,why=Woc.why,picked=Woc.ids,yours=Woc.mine,swapped=Woc.swapped,result=Woc.result})
