end
F.log(1,RLe[4131],string.format(RLe[4282],ipc.label,mpc or RLe[3918],wpc.margin,wpc.calibrated and RLe[4283]or RLe[4284],wpc.trust and string.format(RLe[4285],wpc.trust.ratio)or RLe[4286],Bpc))
local Cpc=W.rec(ipc.key)
local Dpc=O.huntPearls==true and ipc.kind==RLe[2303]and mb.is(ipc.level)
