end
P.simTeam[ipc.key]={uuids=Cpc.winTeam,names=Npc,ids=Opc,won=true,wave=rpc.total,better=gb.sig(Fpc)~=wpc.sig,cur={won=wpc.won,wave=wpc.wave},at=os.time(),label=ipc.label,base=wpc.sig,why=RLe[4287]}
pcall(gb.explainSave,ipc.key,ipc.label,rpc,Fpc,{string.format(RLe[4288],tostring(wpc.margin)),RLe[4289],Mpc and string.format(RLe[4290],Lpc.ratio or 0)or string.format(RLe[4291],Kpc.wave,Cpc.winTeamN or 1)},gb.sig(Fpc)~=wpc.sig,spc,{won=Kpc.won,wave=Kpc.wave,total=rpc.total,lastWin=Cpc.winTeamN or 1})
F.log(1,RLe[4131],string.format(RLe[4292],ipc.label,table.concat(Npc,RLe[2404]),Mpc and string.format((Lpc.ratio or 0)<0.1 and RLe[4290]or RLe[4293],Lpc.ratio or 0)or string.format(RLe[4294],Kpc.wave),Cpc.winTeamN or 1))
return wpc
end
