return type(sBc)==RLe[2280]and tonumber(sBc.k)or 1
end
function jb.applyK(tBc,uBc)
local vBc=jb.roomK(uBc)
if tBc and vBc>1 then
tBc.hpScale=(tonumber(tBc.hpScale)or 1)*vBc
tBc.roomK=vBc
end
return vBc
end
function jb.roomLearn(wBc)
if wBc or bb.kind~=RLe[2306]or bb.roomLearned then
return
end
local xBc=P.dg.room
local yBc,zBc=bb.pred,bb.calRun
if type(xBc)~=RLe[2280]or xBc.seed==nil or type(yBc)~=RLe[2280]or not yBc.won or type(zBc)~=RLe[2280]then
return
end
local function ABc(BBc,CBc)
return type(BBc)==RLe[2280]and tonumber(BBc[CBc]or BBc[tostring(CBc)])or nil
end
local DBc={}
for EBc=2,bb.wave()do
local FBc,GBc=ABc(zBc.alive,EBc),ABc(yBc.aliveAt,EBc)
if FBc and GBc and FBc>0 and GBc>0 then
table.insert(DBc,FBc/GBc)
end
end
if#DBc<3 then
return
end
table.sort(DBc)
local HBc=DBc[math.ceil(#DBc/2)]
bb.roomLearned=true
if HBc<=1.05 then
return
end
P.dg.roomK=type(P.dg.roomK)==RLe[2280]and P.dg.roomK or{}
local IBc=tostring(xBc.seed)
local JBc=P.dg.roomK[IBc]
local KBc=math.min(jb.ROOM_K_MAX,jb.roomK(IBc)*HBc)
P.dg.roomK[IBc]={k=KBc,n=(type(JBc)==RLe[2280]and tonumber(JBc.n)or 0)+1,at=os.time(),d=xBc.d}
bb.roomKUp=true
local LBc={}
for MBc,NBc in pairs(P.dg.roomK)do
table.insert(LBc,{s=MBc,at=type(NBc)==RLe[2280]and tonumber(NBc.at)or 0})
end
table.sort(LBc,function(OBc,PBc)
return OBc.at>PBc.at
end)
for QBc=31,#LBc do
P.dg.roomK[LBc[QBc].s]=nil
end
F.log(1,RLe[4384],string.format(RLe[4504],tostring(xBc.d),HBc,KBc))
end
function jb.roomDone(RBc)
pcall(jb.roomLearn,RBc)
if type(P.simTeam)==RLe[2280]and type(P.simTeam.dg)==RLe[2280]then
P.simTeam.dg.stale=true
end
P.dg.playLast=nil
local SBc=tonumber(type(bb.ld._dungeon)==RLe[2280]and bb.ld._dungeon.depth)or(P.pending and tonumber(P.pending.depth))or 1
local TBc=tostring(math.min(4,math.max(1,math.ceil(SBc/5))))
local UBc=P.dg.depth[TBc]or{runs=0,wins=0}
UBc.runs,UBc.wins=(tonumber(UBc.runs)or 0)+1,(tonumber(UBc.wins)or 0)+(RBc and 1 or 0)
P.dg.depth[TBc]=UBc
if bb.pred and bb.pred.won==false then
local VBc=type(P.dg.lossCalls)==RLe[2280]and P.dg.lossCalls or{}
VBc.n,VBc.won=(tonumber(VBc.n)or 0)+1,(tonumber(VBc.won)or 0)+(RBc and 1 or 0)
P.dg.lossCalls=VBc
end
local WBc=jb.data()
local XBc,YBc,ZBc=jb.res(WBc)
jb.note(string.format(RLe[4505],SBc,jb.ROOMS,RBc and RLe[4506]or RLe[3068],XBc,YBc,ZBc,jb.lives(WBc)))
P.dg.teams=type(P.dg.teams)==RLe[2280]and P.dg.teams or{}
local _Bc=P.dg.teams[W.teamSig()]or{w=0,l=0}
if RBc then
_Bc.w=(tonumber(_Bc.w)or 0)+1
else
_Bc.l=(tonumber(_Bc.l)or 0)+1
end
P.dg.teams[W.teamSig()]=_Bc
if RBc then
P.dg.lives=5
elseif P.dg.room and P.dg.room.d==SBc then
P.dg.lost=P.dg.lost or{}
local aCc,bCc=tostring(P.dg.room.seed),W.teamSig()
P.dg.lost[aCc]=P.dg.lost[aCc]or{}
P.dg.lost[aCc][bCc]=(P.dg.lost[aCc][bCc]or 0)+1
end
end
function jb.text()
