function bb.buildPath()
bb.samples={}
local sCc=N.PATH and N.PATH.PATH_CACHE and N.PATH.PATH_CACHE[workspace._BASES.pve]
if not sCc then
return
end
for tCc,uCc in pairs(sCc)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[tCc.Name])then
local vCc={}
for wCc,xCc in ipairs(uCc.points or{})do
table.insert(vCc,xCc.part.Position)
end
local yCc=0
for zCc=2,#vCc do
yCc=yCc+(vCc[zCc]-vCc[zCc-1]).Magnitude
end
local ACc=0
for BCc=2,#vCc do
local CCc,DCc=vCc[BCc-1],vCc[BCc]
local ECc=(DCc-CCc).Magnitude
local FCc=math.max(1,math.floor(ECc/2))
for GCc=0,FCc-1 do
local HCc=CCc:Lerp(DCc,GCc/FCc)
table.insert(bb.samples,{pos=HCc,prog=(ACc+ECc*GCc/FCc)/math.max(1,yCc),lane=tCc.Name})
end
ACc=ACc+ECc
end
if vCc[#vCc]then
table.insert(bb.samples,{pos=vCc[#vCc],prog=1,lane=tCc.Name})
end
end
end
pcall(bb.readHidden,sCc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local ICc=tonumber(bb.ld and bb.ld._portal_lanes)
local JCc=gb.laneList(bb.samples)
if ICc and ICc>=1 and JCc and#JCc>ICc then
bb.laneWant=ICc
end
bb.laneTotal=JCc and#JCc or 1
bb.countLanes()
end
function bb.readHidden(KCc)
local LCc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(LCc)~=RLe[2280]or not next(LCc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local MCc
for NCc,OCc in pairs(KCc)do
if LCc[NCc.Name]and type(OCc.points)==RLe[2280]and#OCc.points>=2 then
local PCc={}
for QCc,RCc in ipairs(OCc.points)do
PCc[QCc]=U.flat(RCc.part.Position)
end
local SCc={}
for TCc,UCc in ipairs(bb.samples)do
local VCc=tostring(UCc.lane)
SCc[VCc]=SCc[VCc]or{}
table.insert(SCc[VCc],UCc)
end
local WCc,XCc
for YCc,ZCc in pairs(SCc)do
local _Cc=0
for aDc=1,#PCc,math.max(1,math.floor(#PCc/20))do
local bDc=math.huge
for cDc,dDc in ipairs(ZCc)do
local eDc=(U.flat(dDc.pos)-PCc[aDc]).Magnitude
if eDc<bDc then
bDc=eDc
end
end
_Cc=_Cc+bDc
end
if not XCc or _Cc<XCc then
WCc,XCc=YCc,_Cc
end
end
local fDc,gDc,hDc,iDc,jDc,kDc={},nil,nil,nil,0,0
for lDc,mDc in ipairs(PCc)do
local nDc,oDc=nil,math.huge
for pDc,qDc in ipairs(SCc[WCc])do
local rDc=(U.flat(qDc.pos)-mDc).Magnitude
if rDc<oDc then
oDc,nDc=rDc,qDc.prog
end
end
kDc=math.max(kDc,oDc)
if hDc then
local sDc=nDc-hDc
local tDc=(sDc>0.002 and 1)or(sDc< -0.002 and-1)or iDc
if iDc and tDc and tDc~=iDc then
table.insert(fDc,math.floor(hDc*1000+0.5)/1000)
end
iDc,jDc=tDc or iDc,jDc+math.abs(sDc)
else
gDc=nDc
end
hDc=nDc
if lDc%50==0 then
task.wait()
end
end
if hDc and kDc<=8 then
table.insert(fDc,math.floor(hDc*1000+0.5)/1000)
MCc=MCc or{}
MCc[NCc.Name]={from=math.floor((gDc or 0)*1000+0.5)/1000,len=math.floor(jDc*1000+0.5)/1000,turns=fDc,road=WCc}
end
end
end
if not MCc then
return
end
local uDc=bb.ld.map
P.maps[uDc]=P.maps[uDc]or{}
local vDc=P.maps[uDc].hidden
P.maps[uDc].hidden=MCc
if type(vDc)~=RLe[2280]then
for wDc,xDc in pairs(MCc)do
F.log(1,RLe[2968],string.format(RLe[4520],wDc,xDc.len,tostring(xDc.road),math.floor((#xDc.turns-1)/2)))
end
F.saveSoon()
end
end
function bb.countLanes()
local yDc,zDc,ADc={},0,0
for BDc,CDc in ipairs(bb.samples)do
local DDc=tostring(CDc.lane)
if not yDc[DDc]then
zDc=zDc+1
end
yDc[DDc]=(yDc[DDc]or 0)+1
ADc=ADc+1
end
bb.laneCount={n=zDc,by=yDc,avg=zDc>0 and ADc/zDc or 1}
if zDc>=2 then
local EDc,FDc=pcall(gb.laneSep,bb.samples)
local GDc=P.maps[bb.mapKey()]
if EDc and FDc and type(GDc)==RLe[2280]then
GDc.sep=FDc
end
end
end
bb.LANE_WAIT=3
function bb.portalLanes()
if not bb.laneWant or bb.laneCut then
return true
end
if bb.planning then
return false
end
local HDc,IDc={},0
for JDc,KDc in ipairs(workspace._UNITS:GetChildren())do
local LDc=KDc:FindFirstChild(RLe[2352])
if LDc and LDc:FindFirstChild(RLe[4521])and LDc.player.Value==nil and LDc:FindFirstChild(RLe[4522])and KDc:FindFirstChild(RLe[3636])then
local MDc=tostring(LDc.lane.Value)
if not HDc[MDc]then
HDc[MDc]=true
IDc=IDc+1
end
end
end
if IDc==0 then
if U.now()-(bb.startT or U.now())>45 then
bb.laneWant=nil
F.log(1,RLe[2968],RLe[4523])
return true
end
return false
end
bb.laneFirst=bb.laneFirst or U.now()
if IDc<bb.laneWant and U.now()-bb.laneFirst<bb.LANE_WAIT then
return false
end
local NDc,ODc={},{}
for PDc,QDc in ipairs(bb.samples)do
if HDc[tostring(QDc.lane)]then
table.insert(NDc,QDc)
end
end
if#NDc==0 then
bb.laneWant=nil
return true
end
for RDc in pairs(HDc)do
table.insert(ODc,RDc)
end
table.sort(ODc)
bb.samples,bb.laneCut=NDc,table.concat(ODc,RLe[2610])
bb.countLanes()
local SDc,TDc=pcall(bb.buildCandidates)
if not SDc then
F.log(1,RLe[2289],RLe[4524]..tostring(TDc))
end
F.log(1,RLe[2968],string.format(RLe[4525],bb.laneWant,bb.laneCut))
if bb.info and O.simSpots and not bb.joinedMid and not bb.random and not bb.infinite and not bb.trialId then
bb.planning=U.now()
task.spawn(function()
local UDc,VDc=pcall(bb.planSpots)
bb.planning=nil
if not UDc then
F.log(1,RLe[2289],RLe[4526]..tostring(VDc))
end
end)
end
return true
end
function bb.buildWaves()
local WDc=bb.ld
local XDc=WDc and WDc._dungeon and type(WDc._override_waves)==RLe[2280]and WDc._override_waves or nil
local YDc=WDc and N.Waves[(XDc and XDc.template)or WDc.waves or WDc.id]
local ZDc
if type(YDc)==RLe[2280]then
ZDc=YDc.override_waves or YDc.waves
if not ZDc and YDc.template and N.Waves[YDc.template]then
ZDc=N.Waves[YDc.template].waves or N.Waves[YDc.template].override_waves
end
end
bb.waveList=U.list(ZDc)
bb.infinite=WDc and(WDc._gamemode==RLe[2305]or WDc.infinite)and gb.unbound(WDc)or false
if bb.infinite then
bb.waveList={}
bb.total=math.max(30,math.floor(W.infReach(bb.key)+0.5))
return
end
bb.total=(WDc and type(WDc._dungeon)==RLe[2280]and 15)or tonumber(WDc and WDc._override_infinite_bound_waves)or gb.boundEnd(WDc,#bb.waveList,bb.key)or(#bb.waveList>0 and#bb.waveList)or 15
end
function bb.infExtend()
if bb.infinite and bb.wave()+5>bb.total then
bb.total=bb.wave()+10
end
end
function bb.infWave(_Dc)
bb.infWaveAt=bb.infWaveAt or{}
bb.infWaveAt[_Dc]=bb.infWaveAt[_Dc]or U.now()
bb.infExtend()
local aEc=math.floor(tonumber(O.infLeaveWave)or 0)
if aEc>0 and _Dc>=aEc and not bb.stopping and ab.partyRole()~=RLe[3964]and bb.kind~=RLe[2750]then
bb.stopping=true
F.log(1,RLe[2968],string.format(RLe[4527],_Dc))
local bEc,cEc=pcall(bb.sellAll)
if not bEc then
F.log(1,RLe[2289],RLe[4528]..tostring(cEc))
end
end
if O.trainLeave and not bb.stopping then
local dEc,eEc=pcall(bb.trainLeave,_Dc)
if not dEc then
F.log(1,RLe[2289],RLe[4529]..tostring(eEc))
end
end
if O.infiniteStop and not bb.stopping and ab.partyRole()~=RLe[3964]and bb.kind~=RLe[2750]then
local fEc,gEc=pcall(bb.infStop,_Dc)
if not fEc then
F.log(1,RLe[2289],RLe[4530]..tostring(gEc))
end
end
local hEc=W.infTier(_Dc-1)
if hEc<=0 or hEc==bb.infTierSeen then
return
end
bb.infTierSeen=hEc
task.delay(5,function()
if not F.alive then
return
end
local iEc=N.prof()
local jEc=iEc and iEc.daily_infinite_reward_claims and iEc.daily_infinite_reward_claims[bb.ld.id]
local kEc=type(jEc)==RLe[2280]and(tonumber(jEc.highest_claimed_wave)or 0)>=hEc and os.time()-(tonumber(jEc.highest_claim_time)or 0)<900
if kEc then
P.infLive=true
end
F.log(1,RLe[2968],string.format(RLe[4531],hEc,kEc and RLe[4532]or RLe[4533]))
end)
end
function bb.infStop(lEc)
local mEc=0
for nEc,oEc in ipairs(U.list(N.GS.DAILY_INFINITE_REWARDS))do
mEc=math.max(mEc,tonumber(oEc.wave)or 0)
end
if mEc<=0 or lEc<=mEc+1 then
return
end
local pEc=P.train.on
if bb.trainee and pEc and pEc.have+(pEc.got or 0)+(bb.trainTk or 0)<pEc.need then
return
end
if not ab.every(RLe[4534],60)then
return
end
local qEc=W.rec(bb.key)
local rEc=tonumber(qEc.timed)or 0
local sEc=W.INF_PAY
local tEc
if lEc>=(sEc.cap+sEc.less)/sEc.per then
tEc=0
else
local uEc=bb.infWaveAt or{}
local vEc,wEc=uEc[lEc],uEc[lEc-5]
if vEc and wEc and vEc>wEc then
tEc=sEc.per*5/((vEc-wEc)/60)
end
if not tEc then
tEc=(rEc>0 and(qEc.sec or 0)>0)and math.max(0.5,(qEc.gems or 0)/(qEc.sec/60))or 2.5
end
end
local xEc=pcall(W.pick)
local yEc
for zEc,AEc in ipairs(xEc and W.lastScored or{})do
if AEc.kind~=RLe[2305]and(not yEc or(AEc.score or 0)>(yEc.score or 0))then
yEc=AEc
end
end
if not yEc or(yEc.score or 0)<=tEc then
return
end
bb.stopping=true
F.log(1,RLe[2968],string.format(RLe[4535],lEc,tEc,yEc.score,yEc.label))
bb.sellAll()
end
function bb.trainLeave(BEc)
local CEc=P.train.on
if not(bb.infinite and bb.trainee and CEc)then
return
end
bb.trainCount()
local DEc=CEc.have+(CEc.got or 0)+(bb.trainTk or 0)
if DEc<CEc.need then
return
end
local EEc,FEc,GEc=pcall(W.infDaily,N.prof(),bb.ld.id,(W.infReach(bb.key)))
if EEc and(FEc or 0)>0 and GEc>0 and BEc<=GEc then
F.status(RLe[3601],string.format(RLe[4536],V.name(CEc.id),CEc.what,GEc))
return
end
bb.stopping=true
F.log(1,RLe[2968],string.format(RLe[4537],V.name(CEc.id),CEc.what,U.fmt(DEc),U.fmt(CEc.need),BEc))
bb.sellAll()
end
function bb.sellAll()
task.spawn(function()
local HEc={}
for IEc,JEc in ipairs(bb.mine or{})do
local KEc=JEc:FindFirstChild(RLe[2352])
local LEc=KEc and KEc:FindFirstChild(RLe[2673])and N.Units[KEc.id.Value]
if not(LEc and LEc.unsellable)then
table.insert(HEc,JEc)
end
end
local function MEc(NEc)
local OEc=NEc:FindFirstChild(RLe[2352])
return OEc and OEc:FindFirstChild(RLe[2673])and V.isFarm(OEc.id.Value)or false
end
table.sort(HEc,function(PEc,QEc)
return(MEc(PEc)and 1 or 0)<(MEc(QEc)and 1 or 0)
end)
local REc={}
for SEc=1,2 do
local TEc={}
for UEc,VEc in ipairs(SEc==1 and HEc or REc)do
if not F.alive or bb.finished then
return
end
if VEc.Parent and VEc.Parent.Name==RLe[4538]then
local WEc,XEc=F.request(RLe[2479],RLe[2371],VEc)
if XEc~=true then
table.insert(TEc,VEc)
end
task.wait(1.3)
end
end
REc=TEc
end
if#REc>0 then
local YEc={}
for ZEc,_Ec in ipairs(REc)do
table.insert(YEc,_Ec.Name)
end
F.log(1,RLe[2968],RLe[4539]..table.concat(YEc,RLe[2404])..RLe[4540])
end
end)
end
function bb.waveReward(aFc)
