function bb.progressAt(cFc)
local dFc,eFc,fFc=0,math.huge,nil
local gFc=U.flat(cFc)
for hFc,iFc in ipairs(bb.samples)do
local jFc=(U.flat(iFc.pos)-gFc).Magnitude
if jFc<eFc then
eFc,dFc,fFc=jFc,iFc.prog,iFc.lane
end
end
return dFc,eFc,fFc~=nil and tostring(fFc)or nil
end
function bb.pruneMine()
local kFc=bb.mine
if type(kFc)~=RLe[2280]then
