local ucd=tcd._stats
local vcd=V.rows(ucd.id.Value)
local wcd=vcd and vcd[math.min(ucd.upgrade.Value,vcd.max)]
local xcd=wcd and wcd.atk and V.attackInfo(wcd.atk,wcd.range)
if xcd and((xcd.stun or 0)>0 or(xcd.slowTime or 0)>0)then
rcd=rcd+1
