end
local Fcd,Gcd,Hcd=bb.buffShort(Ecd)
local Icd=V.stackCap(Ecd.attack)
local Jcd,Kcd=pcall(V.range,Dcd.u,0)
Kcd=(Jcd and tonumber(Kcd)or 15)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local Lcd=Icd and O.community and tonumber(Ecd.time)and tonumber(Hcd)
local function Mcd(Ncd,Ocd)
local Pcd=math.floor(Ncd*Ecd.time/math.max(1,Hcd)+0.001)
return math.min(Icd,(1+Ocd)^Pcd-1)
end
local Qcd=0
for Rcd,Scd in ipairs(Fcd)do
local Tcd=0
for Ucd,Vcd in ipairs(Fcd)do
if(Vcd.pos-Scd.pos).Magnitude<=Kcd then
local Wcd=Ecd.types[Vcd.base]
