Xcd=math.max(0,(Mcd(Zcd,Wcd)-Ycd)/(Zcd-Vcd.n))
elseif Icd then
Xcd=math.max(0,math.min(Icd,(Vcd.n+1)*Wcd*Ecd.uptime)-math.min(Icd,Vcd.n*Wcd*Ecd.uptime))
