if skd then
table.insert(pkd,{f=U.flat(skd),p=skd})
end
end
local tkd,ukd
local vkd=math.max(1,math.floor(#pkd/150))
for wkd=1,#pkd,vkd do
local xkd=pkd[wkd].f
local ykd=true
for zkd,Akd in ipairs(ikd)do
if(Akd-xkd).Magnitude<=hkd+2 then
ykd=false
break
end
end
if ykd then
local Bkd=0
for Ckd,Dkd in ipairs(pkd)do
if(Dkd.f-xkd).Magnitude<=hkd*bb.GRIF_ROOM then
Bkd=Bkd+1
