if not Kkd or Kkd.m~=Jkd.m then
return
end
local Lkd={}
for Mkd,Nkd in ipairs(Kkd.fodder)do
Lkd[Nkd]=true
end
for Okd= #Ekd,1,-1 do
if Ekd[Okd].m and Lkd[Ekd[Okd].m]then
table.remove(Ekd,Okd)
end
end
Jkd.more=false
