end
local Pkd=bb.depth and bb.depth.units>0 and bb.depth.covEnd or 1
if(bb.pressure or 0)>=math.min(O.dangerReach,Pkd*0.9)*0.8 or(bb.depth and bb.depth.leak)then
return
end
local Qkd=math.max(1,Kkd.need-Kkd.yen)
local Rkd=(bb.info and tonumber(bb.info.waveSec))or 20
local Skd=math.max(1,tonumber(bb.incomeRate)or((((bb.coming and bb.coming[1]and bb.coming[1].reward)or 500)+(tonumber(bb.farmNow)or 0))/Rkd))
local Tkd=math.max(0,Qkd-Fkd)/Skd
local Ukd=(bb.teamDps or 0)/(1+U.clamp(tonumber(bb.buffLevel())or 0,0,2))/V.GRIF.need/(1+Tkd/(6*Rkd))
if Ukd<=0 then
return
end
local Vkd=string.format(RLe[4891],U.fmt(Kkd.yen),U.fmt(Kkd.need))
for Wkd,Xkd in ipairs(Kkd.fodder)do
local Ykd=Xkd._stats
local Zkd=Ykd.id.Value
local _kd=V.rows(Zkd)
local ald=tonumber(Ykd.upgrade.Value)or 0
local bld=_kd and _kd[ald+1]
if bld and ald<_kd.max and not((bb.upFail[Xkd]or 0)>=3 and U.now()-(bb.upFailAt[Xkd]or 0)<60)then
local cld=1
pcall(function()
cld=N.USC.calculate_upgrade_cost_multiplier(Xkd,N.session())
end)
local dld=bld.cost*cld
Jkd.more=true
if Kkd.yen<Kkd.need then
table.insert(Ekd,{grif=true,cost=dld,gain=Ukd*dld,m=Xkd,what=string.format(RLe[4892],V.name(Zkd),ald+1,Vkd)})
end
end
end
if Kkd.yen>=Kkd.need or bb.fieldCount()>=bb.FIELD_MAX or bb.placePaused()then
return
end
for eld,fld in ipairs(Jkd.fodder)do
if#(Hkd[fld.uuid]or{})<V.cap(fld.u)and(bb.noSpot[fld.uuid]or 0)<3 then
local gld=(tonumber(fld.data.cost)or 0)*Gkd
Jkd.more=true
table.insert(Ekd,{place=true,grif=true,cost=gld,gain=Ukd*gld,e=setmetatable({_grif=true},{__index=fld}),what=string.format(RLe[4893],V.name(fld.id),Vkd)})
end
end
end
function bb.grifEggGain(hld,ild)
local jld=bb.grifS
if not(bb.grifOn()and jld and not jld.done and not jld.off and bb.grifLong())then
return 0
end
local kld=bb.depth and bb.depth.units>0 and bb.depth.covEnd or 1
if(bb.pressure or 0)>=math.min(O.dangerReach,kld*0.9)*0.8 or(bb.depth and bb.depth.leak)then
return 0
end
local lld=(bb.info and tonumber(bb.info.waveSec))or 20
local mld=math.max(1,tonumber(bb.incomeRate)or((((bb.coming and bb.coming[1]and bb.coming[1].reward)or 500)+(tonumber(bb.farmNow)or 0))/lld))
local nld=math.max(0,V.GRIF.need+(tonumber(hld)or 0)-(tonumber(ild)or 0))/mld
local pld=(bb.teamDps or 0)/(1+U.clamp(tonumber(bb.buffLevel())or 0,0,2))/V.GRIF.need/(1+nld/(6*lld))
