function bb.sacrificeOk(Fld,Gld)
local Hld=O.griffinSacrifice
if Hld==RLe[2412]then
return nil,nil,true
end
if Hld==RLe[2413]then
return false
end
local Ild=bb.grifOn()
if Ild and(bb.grifS.done or bb.grifS.off)then
if bb.grifS.done then
return false
end
Ild=false
end
if not bb.infinite and bb.total and bb.wave()>=bb.total-2 then
return false
end
local Jld,Kld=U.flat(Fld:GetPivot().Position),tonumber(Gld.range.Value)or 0
local Lld,Mld,Nld,Old=0,{},0,{}
for Pld,Qld in ipairs(bb.mine or{})do
local Rld=Qld~=Fld and Qld:FindFirstChild(RLe[2352])
local Sld=Rld and Rld:FindFirstChild(RLe[2673])and Rld.id.Value
if Sld and(U.flat(Qld:GetPivot().Position)-Jld).Magnitude<=Kld then
if V.sacFodder(Sld)then
Lld=Lld+1
local Tld=Rld:FindFirstChild(RLe[4564])and tonumber(Rld.total_spent.Value)or 0
Nld=Nld+Tld
Old[Qld]=Tld
else
Mld[V.name(Sld)]=true
end
end
end
if next(Mld)then
bb.sacSaid=bb.sacSaid or{}
if not bb.sacSaid[Fld]then
bb.sacSaid[Fld]=true
local Uld={}
for Vld in pairs(Mld)do
table.insert(Uld,Vld)
end
table.sort(Uld)
F.log(1,RLe[4875],string.format(RLe[4901],V.name(Gld.id.Value),table.concat(Uld,RLe[2404])))
end
