if not Zld then
return false
end
Wld.cast={m=Fld,at=U.now(),units=Old,yen=Nld}
return true,string.format(RLe[4902],Lld,Lld==1 and RLe[1199]or RLe[2126],U.fmt(Nld),U.fmt(Yld))
end
return true,string.format(RLe[4903],Lld,Lld==1 and RLe[1199]or RLe[2126],U.fmt(Nld))
end
function bb.aoeActive(_ld)
