end
function bb.aoePoint(bmd,cmd)
local dmd=U.flat(bmd:GetPivot().Position)
local emd={}
for fmd,gmd in ipairs(bb.samples or{})do
if(U.flat(gmd.pos)-dmd).Magnitude<=cmd*0.95 then
table.insert(emd,gmd)
end
end
if#emd==0 then
return nil
end
local hmd,imd,jmd,kmd=nil,-1,-1,0
for lmd,mmd in ipairs(emd)do
local nmd,omd=0,0
for pmd,qmd in ipairs(bb.enemies or{})do
local rmd=qmd.pos and(U.flat(qmd.pos)-U.flat(mmd.pos)).Magnitude or math.huge
if rmd<=12 then
omd=omd+1
nmd=nmd+(1-rmd/12*0.9)*(qmd.boss and 3 or 1)
end
end
if nmd>imd+1e-6 or(math.abs(nmd-imd)<=1e-6 and mmd.prog>jmd)then
hmd,imd,jmd,kmd=mmd,nmd,mmd.prog,omd
end
end
if kmd<=0 then
local smd=type(P.maps[bb.mapKey()])==RLe[2280]and P.maps[bb.mapKey()].dens or nil
if type(smd)==RLe[2280]and#smd>0 then
local tmd= -1
for umd,vmd in ipairs(emd)do
local wmd=tonumber(smd[math.max(1,math.min(#smd,math.floor(vmd.prog* #smd)+1))])or 0
if wmd>tmd then
hmd,tmd=vmd,wmd
end
end
else
hmd=emd[math.ceil(#emd/2)]
end
end
return hmd and hmd.pos or nil,kmd
end
function bb.actives()
if not O.actives or bb.activeBusy then
return
end
local xmd=tick()
local ymd=U.now()
for zmd,Amd in ipairs(bb.mine)do
local Bmd=Amd._stats
local Cmd,Dmd,Emd=Bmd:FindFirstChild(RLe[2398]),Bmd:FindFirstChild(RLe[4566]),Bmd:FindFirstChild(RLe[4863])
if Cmd and Dmd and Emd and Cmd.Value~=RLe[4904]and Cmd.Value~=RLe[1199]and not(Bmd:FindFirstChild(RLe[2673])and Bmd.id.Value==RLe[4542])then
