local ind=Fmd.ally and Wmd>0 and bb.buffLevel(Fmd.ally.types)or 0
local jnd=Wmd>0 and Fmd.ally and O.community and ind>0 and((gnd==nil and Xmd-ymd>5)or(gnd and gnd.stacks and ind<(gnd.cap or 1)-0.02))
if Vmd>Wmd or jnd then
Imd,Jmd=true,string.format(RLe[4909],Vmd+Wmd)
if jnd and gnd==nil then
Kmd={key=Cmd.Value,types=Fmd.ally.types,before=ind}
