if not Jnd then
Jnd={n=0,sum=0,top=0,stacked=0,single=Fnd}
bb.buffTrack[Dnd]=Jnd
end
Jnd.n,Jnd.sum,Jnd.top=Jnd.n+1,Jnd.sum+Ind,math.max(Jnd.top,Ind)
