mb.CARD_PICKS={RLe[1201],RLe[2298],RLe[2860],RLe[1203]}
function mb.cardPearls(Hod,Iod)
local Jod=mb.pearlsFrom((tonumber(Iod)or 0)+1,50)
local Kod=0
for Lod,Mod in pairs(type(Hod)==RLe[2280]and type(Hod.effects)==RLe[2280]and Hod.effects or{})do
if type(Mod)==RLe[2280]and Mod.type==RLe[2842]then
Kod=Kod+math.abs(tonumber(Mod.amount)or 0)*Jod
end
end
return Kod
end
function mb.cardLuck(Nod)
local Ood=0
for Pod,Qod in pairs(type(Nod)==RLe[2280]and type(Nod.effects)==RLe[2280]and Nod.effects or{})do
if type(Qod)==RLe[2280]and Qod.type==RLe[2845]then
