function bb.huntChoose(Rod,Sod)
bb.fhP=bb.fhP or 1
local Tod=mb.floor()
local Uod=(bb.pressure or 0)>=O.safeReach or(bb.depth and bb.depth.leak)
local Vod=mb.weatherStrength(mb.weatherNow())
local Wod=table.find(mb.CARD_PICKS,O.huntCards)and O.huntCards or RLe[1203]
local Xod,Yod,Zod,_od
local apd={}
bb.fhFactors={}
for bpd,cpd in pairs(Rod)do
local dpd,epd=1,{}
for fpd,gpd in pairs(type(cpd)==RLe[2280]and cpd.effects or{})do
if type(gpd)==RLe[2280]then
local hpd=bb.rogueEffect(gpd)
dpd=dpd*hpd
table.insert(epd,bb.effectText(gpd))
end
end
if type(cpd)==RLe[2280]and cpd.weather then
dpd=dpd*mb.weatherStrength(cpd.weather)/math.max(0.05,Vod)
end
if type(cpd)==RLe[2280]and(cpd.title or cpd.name)then
bb.fhFactors[tostring(cpd.title or cpd.name):lower():gsub(RLe[4937],RLe[1199])]=dpd
end
local ipd=type(cpd)==RLe[2280]and mb.cardGems(cpd,Sod)or 0
local jpd=dpd>=1 or(bb.fhP*dpd>=Tod and not Uod)
local kpd=math.log(math.max(0.05,dpd))
local lpd=kpd*mb.STRENGTH_GEMS+(jpd and ipd or-1000)
local mpd=mb.cardLuck(cpd)
if Wod==RLe[1201]and jpd and mpd>0 then
lpd=2e6+mpd*1e4+ipd
elseif Wod==RLe[2298]and jpd then
lpd=1e6+mb.cardPearls(cpd,Sod)*10+ipd+kpd
elseif Wod==RLe[2860]then
lpd=kpd*1e6+ipd
end
if not Yod or lpd>Yod then
Xod,Yod,Zod,_od=bpd,lpd,dpd,ipd
end
table.insert(apd,string.format(RLe[4938],tostring(bpd),tostring(type(cpd)==RLe[2280]and cpd.title or RLe[2531]),(type(cpd)==RLe[2280]and cpd.weather)and(RLe[3009]..tostring(cpd.weather)..RLe[2961])or RLe[1199],tostring(type(cpd)==RLe[2280]and cpd.option_type or RLe[2531]),dpd,math.floor(ipd+0.5),table.concat(epd,RLe[2932])))
end
return Xod,Zod,_od,apd,Tod,Uod,Wod
end
