bb.HUNT_WEAK_RUNS=8
bb.HUNT_WEAK_KINDS={RLe[2304],RLe[2301],RLe[2305],RLe[2302],RLe[2306],RLe[2758],RLe[4961],RLe[2300],RLe[2299],RLe[2749]}
function bb.huntWeakText()
