function bb.rogueShare(Eqd)
if not Eqd then
return 0.5
end
local Fqd=tostring(Eqd):gsub(RLe[4221],RLe[1199])
local Gqd,Hqd=0,0
for Iqd,Jqd in ipairs(bb.mine or{})do
local Kqd=Jqd._stats.id.Value
if not V.isFarm(Kqd)then
local Lqd,Mqd=pcall(bb.liveDps,Jqd,Kqd)
Mqd=Lqd and Mqd or 0
local Nqd=V.types(Kqd)
Gqd=Gqd+Mqd
if Nqd[Fqd]or Nqd[Fqd..RLe[2499]]then
Hqd=Hqd+Mqd
end
end
end
local Oqd=0
for Pqd,Qqd in ipairs(bb.mine or{})do
if not V.isFarm(Qqd._stats.id.Value)then
Oqd=Oqd+1
end
end
local Rqd=Oqd/(Oqd+4)
return Rqd*(Gqd>0 and Hqd/Gqd or 0.5)+(1-Rqd)*0.5
end
function bb.resistOf(Sqd)
local Tqd=V.types(Sqd)
local Uqd=0
for Vqd,Wqd in pairs(bb.fhResist or{})do
local Xqd=tostring(Vqd):gsub(RLe[4221],RLe[1199])
if Tqd[Xqd]or Tqd[Xqd..RLe[2499]]then
Uqd=math.max(Uqd,Wqd/100)
end
end
return math.min(0.95,Uqd)
end
function bb.rogueEffect(Yqd)
local Zqd,_qd,ard=Yqd.type,tonumber(Yqd.amount)or 0,tostring(Yqd.stat or RLe[1199])
if Zqd==RLe[2842]then
return 1,math.abs(_qd)
end
if Zqd==RLe[4348]or Zqd==RLe[4353]or Zqd==RLe[4349]then
if ard==RLe[2730]then
return math.max(0.3,1+_qd),0
end
if ard==RLe[2548]then
return math.max(0.5,1+_qd/2),0
end
if ard:find(RLe[3091])then
return 1/math.max(0.3,1+_qd),0
end
return 1,0
end
if Zqd==RLe[4969]then
if ard==RLe[2730]then
return math.max(0.3,_qd),0
end
if ard==RLe[2548]then
return math.max(0.5,1+(_qd-1)/2),0
end
if ard:find(RLe[3091])then
return 1/math.max(0.3,_qd),0
end
return 1,0
end
if Zqd==RLe[4355]then
return 1+_qd/3,0
end
if Zqd==RLe[4361]then
return 1/math.max(0.3,1+_qd),0
end
if Zqd==RLe[4970]then
return math.max(0.2,1-bb.rogueShare(Yqd.damage_type)*(1-100/(100+_qd))),0
end
if Zqd==RLe[4971]then
return 1+bb.rogueShare(Yqd.damage_type)*_qd,0
end
if Zqd==RLe[4972]then
return math.max(0.5,1-_qd*0.5),0
