function bb.learn()
local drd=bb.calRun and bb.calRun.potBy
if type(drd)~=RLe[2280]then
return
end
pcall(bb.sampleHelpers,true)
local erd={}
for frd,grd in pairs(bb.ownDealt or{})do
if not V.isFarm(grd.id)then
erd[grd.id]=(erd[grd.id]or 0)+(tonumber(grd.v)or 0)
end
end
for hrd,ird in pairs(bb.helperDealt or{})do
if ird.owner and V.SUMMONER[ird.owner]and not V.droneHelper(ird)then
erd[ird.owner]=(erd[ird.owner]or 0)+(tonumber(ird.v)or 0)
end
end
local jrd=type(bb.calRun.potExp)==RLe[2280]and bb.calRun.potExp or{}
local krd,lrd=0,0
local mrd={}
for nrd,ord in pairs(drd)do
if ord>0 then
krd,lrd=krd+(erd[nrd]or 0),lrd+ord
local prd=tonumber(jrd[nrd])or ord
if prd>0 then
table.insert(mrd,{id=nrd,r=(erd[nrd]or 0)/prd,w=prd})
end
end
end
if krd<=0 or lrd<=0 then
return
end
table.sort(mrd,function(qrd,rrd)
return qrd.r<rrd.r
end)
local function srd(trd)
local urd,vrd=0,0
for wrd,xrd in ipairs(mrd)do
if xrd.id~=trd then
urd=urd+xrd.w
end
end
if urd<=0 then
return nil
end
for yrd,zrd in ipairs(mrd)do
if zrd.id~=trd then
vrd=vrd+zrd.w
if vrd>=urd/2 then
return zrd.r
end
end
end
end
bb.lastEff={}
for Ard,Brd in pairs(drd)do
local Crd=srd(Ard)
if Brd>0 and Brd/lrd>0.02 and Crd and Crd>0 then
local Drd=P.learn[Ard]or{eff=1,n=0,v=6}
V.learnUp(Ard,Drd)
local Erd=math.max(0.02,0.25*math.sqrt(30/(30+Drd.n)))
local Frd=U.clamp(((erd[Ard]or 0)/Brd)/Crd,0.2,6)
bb.lastEff[Ard]=math.floor(Frd*1000+0.5)/1000
Drd.eff=Drd.eff+(Frd-Drd.eff)*Erd
Drd.n=Drd.n+1
P.learn[Ard]=Drd
end
end
local Grd=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if Grd and next(bb.lastEff)then
P.mapLearn=type(P.mapLearn)==RLe[2280]and P.mapLearn or{}
local Hrd=type(P.mapLearn[Grd])==RLe[2280]and P.mapLearn[Grd]or{}
for Ird,Jrd in pairs(bb.lastEff)do
local Krd=type(Hrd[Ird])==RLe[2280]and Hrd[Ird]or{eff=Jrd,n=0,v=6}
if(tonumber(Krd.v)or 0)<4 then
Krd.eff,Krd.v=(tonumber(Krd.eff)or Jrd)*V.secRescale(Ird),4
end
if(tonumber(Krd.v)or 0)<5 then
Krd.eff,Krd.v=(tonumber(Krd.eff)or Jrd)*(V.sumRescale(Ird)or 1),5
end
if(tonumber(Krd.v)or 0)<6 then
Krd.eff,Krd.v=(tonumber(Krd.eff)or Jrd)*(1-(V.SUMMONER[Ird]and V.SUMMONER[Ird].droneShare or 0)),6
end
local Lrd=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(Krd.n)or 0))))
Krd.eff=(tonumber(Krd.n)or 0)==0 and Jrd or((tonumber(Krd.eff)or Jrd)+(Jrd-(tonumber(Krd.eff)or Jrd))*Lrd)
Krd.n=(tonumber(Krd.n)or 0)+1
Hrd[Ird]=Krd
end
Hrd._at=os.time()
P.mapLearn[Grd]=Hrd
if U.count(P.mapLearn)>80 then
local Mrd,Nrd
for Ord,Prd in pairs(P.mapLearn)do
if not Nrd or(tonumber(Prd._at)or 0)<Nrd then
Mrd,Nrd=Ord,tonumber(Prd._at)or 0
end
end
P.mapLearn[Mrd]=nil
end
end
end
function bb.randomTeam()
