bb.BASE_WIN,bb.BASE_MARGIN,bb.BASE_SOON,bb.BASE_END=10,1.3,45,0.97
function bb.baseVerdict(Txd,Uxd)
local Vxd=(Uxd.t or 0)-(Txd.t or 0)
if Vxd<bb.BASE_WIN-1 then
return false
end
local Wxd=((tonumber(Txd.base)or 0)-(tonumber(Uxd.base)or 0))/Vxd
if Wxd<=0 or(tonumber(Uxd.base)or 0)<=0 then
return false
end
local Xxd=Uxd.base/Wxd
local Yxd,Zxd=0,0
local _xd,ayd=Txd.foes or{},Uxd.foes or{}
for byd,cyd in pairs(ayd)do
if cyd.prog>=bb.BASE_END then
Yxd=Yxd+cyd.hp
local dyd=_xd[byd]
if dyd then
Zxd=Zxd+math.max(0,dyd.hp-cyd.hp)
end
end
end
for eyd,fyd in pairs(_xd)do
if fyd.prog>=bb.BASE_END and not ayd[eyd]then
Zxd=Zxd+fyd.hp
end
end
if Yxd<=0 then
return false
end
local gyd=Zxd/Vxd
local hyd=gyd>0 and Yxd/gyd or math.huge
local iyd={baseTime=Xxd,loss=Wxd,atEnd=Yxd,rate=gyd,killTime=hyd}
return Xxd<bb.BASE_SOON and hyd>Xxd*bb.BASE_MARGIN,iyd
end
