function nb.K.key(Dfe,Efe)
local Ffe,Gfe,Hfe=nb.K,nb.Win,Enum.KeyCode
if Ffe.cur and not(Ffe.cur.obj and Ffe.cur.obj.Parent and Ffe.shown(Ffe.cur.obj))then
Ffe.setFocus(nil)
end
if Ffe.cur and Ffe.cur.listKey and Ffe.cur.listKey(Dfe)then
return true
end
if Dfe==Hfe.PageUp or Dfe==Hfe.PageDown then
local Ife={}
for Jfe,Kfe in pairs(Gfe._tabs)do
table.insert(Ife,{name=Jfe,y=Kfe.btn.AbsolutePosition.Y,on=Kfe.page.Visible})
end
table.sort(Ife,function(Lfe,Mfe)
return Lfe.y<Mfe.y
end)
local Nfe=1
for Ofe,Pfe in ipairs(Ife)do
if Pfe.on then
Nfe=Ofe
end
end
Nfe=(Nfe-1+(Dfe==Hfe.PageDown and 1 or-1))% #Ife+1
Ffe.setFocus(nil)
Gfe:SelectTab(Ife[Nfe].name)
return true
end
if Dfe==Hfe.Tab or Dfe==Hfe.Down or Dfe==Hfe.Up then
local Qfe=Ffe.order()
if#Qfe==0 then
return true
end
local Rfe=Dfe==Hfe.Up or(Dfe==Hfe.Tab and Efe)
local Sfe=table.find(Qfe,Ffe.cur)
if not Sfe then
Sfe=Rfe and#Qfe or 1
else
Sfe=(Sfe-1+(Rfe and-1 or 1))% #Qfe+1
end
Ffe.setFocus(Qfe[Sfe])
return true
end
if not Ffe.cur then
return false
end
if Dfe==Hfe.Return or Dfe==Hfe.KeypadEnter or Dfe==Hfe.Space then
if Ffe.cur.activate then
Ffe.cur.activate()
end
return true
end
if Dfe==Hfe.Left or Dfe==Hfe.Right then
if Ffe.cur.adjust then
Ffe.cur.adjust(Dfe==Hfe.Right and 1 or-1)
end
return true
end
if Dfe==Hfe.Escape then
Ffe.setFocus(nil)
return true
end
